impl Solution {
    pub fn max_in_table(n: u32) -> u32 {
        let n = n as usize;
        let mut dp = vec![vec![0; n]; n];
        for i in 0..n {
            for j in 0..n {
                if i == 0 || j == 0 {
                    dp[i][j] = 1;
                } else {
                    dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
                }
            }
        }
        dp[n - 1][n - 1] as u32
    }
}

